script:
frappe.ui.form.on("MJML Email Template", {
    refresh(frm) {
        frm.add_custom_button("Preview Email", () => {
            frappe.prompt(
                [
                    {
                        label: "Sample Lead (optional)",
                        fieldname: "lead",
                        fieldtype: "Link",
                        options: "Lead"
                    }
                ],
                (data) => {
                    frappe.call({
                        method: "legal_management.legal_management.email_campaign.mjml_campaign.preview_mjml_template",
                        args: {
                            template_name: frm.doc.name,
                            lead_name: data.lead
                        },
                        freeze: true,
                        callback: function (r) {
                            if (!r.message) {
                                frappe.msgprint("No preview HTML returned");
                                return;
                            }
                            show_email_preview(r.message);
                        }
                    });
                },
                "Preview Email",
                "Preview"
            );
        });
    }
});


function show_email_preview(html) {
    const dialog = new frappe.ui.Dialog({
        title: "Email Preview",
        size: "extra-large",
        fields: [
            {
                fieldtype: "HTML",
                fieldname: "preview"
            }
        ]
    });

    dialog.show();

    // Render MJML HTML directly inside the HTML field
    dialog.fields_dict.preview.$wrapper.html(`
        <div style="
            border:1px solid #ddd;
            padding:20px;
            background:#fff;
            max-height:700px;
            overflow:auto;
        ">
            ${html}
        </div>
    `);
}

frappe.ui.form.on("Email Campaign", {
    refresh(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button("Compile MJML", () => {
                frappe.call({
                    method: "legal_management.email_campaign.mjml_campaign.compile_and_attach_mjml",
                    args: {
                        campaign_name: frm.doc.name
                    },
                    freeze: true,
                    callback(r) {
                        frappe.msgprint("MJML compiled & attached to campaign");
                        frm.reload_doc();
                    }
                });
            });
        }
    }
});

frappe.ui.form.on("Email Campaign", {
    refresh(frm) {
        if (!frm.is_new()) {

            frm.add_custom_button("Send Now", () => {
                frappe.confirm(
                    "Send this campaign immediately?",
                    () => {
                        frappe.call({
                            method: "legal_management.email_campaign.send_now.send_campaign_now",
                            args: {
                                campaign_name: frm.doc.name
                            },
                            freeze: true,
                            callback(r) {
                                frappe.msgprint(r.message || "Campaign sent");
                            }
                        });
                    }
                );
            });
        }
    }
});

frappe.ui.form.on('Hearing Outcome', {
    onload(frm) {
        frm.set_query('hearing', () => {
            return {
                filters: [
                    ['Hearing', 'hearing_date', '<=', frappe.datetime.get_today()]
                ]
            };
        });
    }
});

frappe.ui.form.on("Case Interest", {
    refresh(frm) {
        if (
            frm.doc.status === "Interested" &&
            frappe.user.has_role("Customer")
        ) {
            frm.add_custom_button("Accept Case", () => {
                frappe.call({
                    method: "legal_management.api.create_case",
                    args: {
                        case_interest: frm.doc.name
                    },
                    callback(r) {
                        if (!r.exc) {
                            frappe.msgprint("Case created successfully");
                            frappe.set_route("Form", "Case", r.message.case);
                        }
                    }
                });
            });
        }
    }
});

frappe.ui.form.on("Case Request", {
    refresh(frm) {
        if (frm.doc.status === "New" && frappe.user.has_role("Lawyer")) {
            frm.add_custom_button("I'm Interested", () => {
                frappe.call({
                    method: "legal_management.api.create_case_interest",
                    args: {
                        case_request: frm.doc.name

                    },
                    callback(r) {
                        if (!r.exc) {
                            frappe.msgprint("Case Interest successfully recorded");
                            frappe.set_route("Form", "Case Interest", r.message.case);
                        }
                    }
                });
            });
        }
    }
});
